    /**
     * Returns the accumulated length (in milliseconds) up to but not including
     * the given chunk event. The first chunk returns 0; later chunks return
     * the sum of all prior chunk durations.
     */
    public getLengthTo(event: MatrixEvent): number {
        const index = this.events.findIndex(e => e.getId() === event.getId());
        if (index < 0) {
            return 0;
        }

        return this.events.slice(0, index).reduce((length: number, e: MatrixEvent) => {
            return length + this.calculateChunkLength(e);
        }, 0);
    }

    /**
     * Finds the chunk event whose cumulative length so far is greater than or
     * equal to the queried time (inclusive at the boundary), so that
     * `findByTime(totalDuration)` resolves to the last chunk rather than null.
     * @param time The playback time in milliseconds.
     */
    public findByTime(time: number): MatrixEvent | null {
        let lengthSoFar = 0;

        for (const event of this.events) {
            const chunkLength = this.calculateChunkLength(event);
            if (lengthSoFar + chunkLength >= time) {
                return event;
            }
            lengthSoFar += chunkLength;
        }

        return null;
    }
