"""Best Book Award operations for Open Library."""

import logging

from openlibrary.core import db
from openlibrary.core.bookshelves import Bookshelves
from openlibrary.utils import extract_numeric_id_from_olid

logger = logging.getLogger(__name__)


class Bestbook(db.CommonExtras):
    TABLENAME = "bestbook_awards"
    PRIMARY_KEY = ("username", "work_id", "topic")

    class AwardConditionsError(Exception):
        """Raised when the conditions for adding an award are not met."""

    @classmethod
    def prepare_query(
        cls,
        select: str = "*",
        work_id: str | None = None,
        username: str | None = None,
        topic: str | None = None,
    ) -> tuple[str, dict]:
        """Builds the SQL query string and its bound variables for fetching
        awards matching the specified filters.
        """
        query = f"SELECT {select} FROM {cls.TABLENAME}"
        where_clauses = []
        variables = {}
        if work_id is not None:
            where_clauses.append("work_id=$work_id")
            variables['work_id'] = work_id
        if username is not None:
            where_clauses.append("username=$username")
            variables['username'] = username
        if topic is not None:
            where_clauses.append("topic=$topic")
            variables['topic'] = topic
        if where_clauses:
            query += " WHERE " + " AND ".join(where_clauses)
        return query, variables

    @classmethod
    def get_awards(
        cls,
        work_id: str | None = None,
        username: str | None = None,
        topic: str | None = None,
    ) -> list:
        """Returns the list of best book awards matching the specified filters."""
        query, variables = cls.prepare_query(
            select="*", work_id=work_id, username=username, topic=topic
        )
        oldb = db.get_db()
        return list(oldb.query(query, vars=variables))

    @classmethod
    def get_count(
        cls,
        work_id: str | None = None,
        username: str | None = None,
        topic: str | None = None,
    ) -> int:
        """Returns the count of best book awards matching the specified filters."""
        query, variables = cls.prepare_query(
            select="count(*)", work_id=work_id, username=username, topic=topic
        )
        oldb = db.get_db()
        result = oldb.query(query, vars=variables)
        return result[0] if result else 0

    @classmethod
    def get_leaderboard(cls) -> list[dict]:
        """Returns the leaderboard of best books, aggregated as work_id plus
        award count, ordered by count descending.
        """
        oldb = db.get_db()
        query = (
            f"SELECT work_id, count(*) AS cnt FROM {cls.TABLENAME} "
            "GROUP BY work_id ORDER BY cnt DESC"
        )
        return list(oldb.query(query))

    @classmethod
    def add(
        cls,
        username: str,
        work_id: str,
        topic: str,
        comment: str = "",
        edition_id: int | None = None,
    ):
        """Adds an award when conditions are met, otherwise raises
        Bestbook.AwardConditionsError.
        """
        # Validate the read prerequisite before any database access.
        if not Bookshelves.user_has_read_work(username, work_id):
            raise Bestbook.AwardConditionsError(
                "Only books which have been marked as read may be given awards"
            )

        # Validate duplicate conditions from the patron's existing nominations
        # before touching the database.
        if cls.get_awards(work_id=work_id, username=username):
            raise Bestbook.AwardConditionsError(
                f"User {username} has already nominated this work"
            )
        if cls.get_awards(topic=topic, username=username):
            raise Bestbook.AwardConditionsError(
                f"User {username} has already used the topic {topic} for another work"
            )

        oldb = db.get_db()
        return oldb.insert(
            cls.TABLENAME,
            username=username,
            work_id=work_id,
            topic=topic,
            comment=comment,
            edition_id=edition_id,
        )

    @classmethod
    def remove(cls, username: str, work_id: str | None = None, topic: str | None = None) -> int:
        """Removes any award for the username where the work_id or topic matches."""
        oldb = db.get_db()
        where_clauses = ["username=$username"]
        variables = {'username': username}
        if work_id is not None:
            where_clauses.append("work_id=$work_id")
            variables['work_id'] = work_id
        if topic is not None:
            where_clauses.append("topic=$topic")
            variables['topic'] = topic
        return oldb.delete(
            cls.TABLENAME,
            where=" AND ".join(where_clauses),
            vars=variables,
        )
