    def render_system_defaults(self, config):
        """Parse the user system defaults and platform family from the
        running configuration and record the resulting device-wide default
        interface mode and the default L2/L3 enabled states.
        """
        sysdefs = {}
        for line in config.splitlines():
            line = line.strip()
            if line == 'system default switchport':
                sysdefs['system_default_switchport'] = True
            elif line == 'no system default switchport':
                sysdefs['system_default_switchport'] = False
            elif line == 'system default switchport shutdown':
                sysdefs['system_default_switchport_shutdown'] = True
            elif line == 'no system default switchport shutdown':
                sysdefs['system_default_switchport_shutdown'] = False

        device_info = self._device_info(self._module)
        platform = device_info.get('network_os_platform', '')
        for prefix in ('N3K', 'N5K', 'N6K', 'N7K', 'N9K'):
            if platform.startswith(prefix):
                sysdefs['network_os_platform_family'] = prefix
                break

        sysdefs['default_interface_mode'] = 'layer2' if sysdefs.get('system_default_switchport', False) else 'layer3'
        sysdefs['default_l2_enabled'] = not sysdefs.get('system_default_switchport_shutdown', False)
        family = sysdefs.get('network_os_platform_family', '')
        if family in ('N3K', 'N5K', 'N6K'):
            sysdefs['default_l3_enabled'] = True
        elif family in ('N7K', 'N9K'):
            sysdefs['default_l3_enabled'] = False

        self.sysdefs = sysdefs
        return sysdefs
