def _device_info(module):
    """Return device info mapping for the NX-OS device.

    The returned mapping exposes the platform family under the
    ``network_os_platform`` entry.
    """
    conn = get_connection(module)
    caps = conn.get_capabilities()
    device_info = caps.get('device_info') or {}
    platform = device_info.get('network_os_platform', '')
    for prefix in ('N3K', 'N5K', 'N6K', 'N7K', 'N9K'):
        if platform.startswith(prefix):
            device_info['network_os_platform_family'] = prefix
            break
    return device_info


def default_intf_enabled(name='', sysdefs=None, mode=None):
    """Compute the default administrative enabled/shutdown state for an interface.

    :param name: the interface name
    :param sysdefs: the device user system defaults (USD)
    :param mode: the target interface mode ('layer2' or 'layer3')
    :returns: the default enabled state (True/False) or None if undetermined
    """
    sysdefs = sysdefs or {}
    itype = get_interface_type(name)
    if itype in ('loopback', 'portchannel'):
        return True
    if itype == 'ethernet':
        if mode == 'layer2':
            return not sysdefs.get('system_default_switchport_shutdown', False)
        elif mode == 'layer3':
            family = sysdefs.get('network_os_platform_family', '')
            if family in ('N3K', 'N5K', 'N6K'):
                return True
            elif family in ('N7K', 'N9K'):
                return False
    return None


